<script setup>
import { computed, ref } from "vue";
import { useInputState } from "../utils/input-state.js";
const props=defineProps({modelValue:{type:Number,default:0},name:String,label:{type:String,default:"角度"},disabled:Boolean,required:Boolean,step:{type:Number,default:1},size:{type:Number,default:168}});const emit=defineEmits(["update:modelValue","change"]);const root=ref(null),range=ref(null);const {local,update}=useInputState(props,emit,root,v=>Number.isFinite(Number(v))?((Number(v)%360)+360)%360:0);const point=computed(()=>({left:`${50+Math.sin(local.value*Math.PI/180)*42}%`,top:`${50-Math.cos(local.value*Math.PI/180)*42}%`}));function pointer(e){if(props.disabled)return;const r=root.value.getBoundingClientRect(),angle=(Math.atan2(e.clientX-(r.left+r.width/2),-(e.clientY-(r.top+r.height/2)))*180/Math.PI+360)%360;update(Math.round(angle/props.step)*props.step%360,false);}function key(e){if(!['ArrowLeft','ArrowDown','ArrowRight','ArrowUp','Home','End'].includes(e.key))return;e.preventDefault();update(e.key==='Home'?0:e.key==='End'?359.999:(local.value+(e.key==='ArrowRight'||e.key==='ArrowUp'?1:-1)*props.step+360)%360);}
</script>
<template><div ref="root" class="kima-angle-slider" :class="{'kima-angle-slider--disabled':disabled}" :style="{'--kima-angle-size':`${size}px}`}"><div class="kima-angle-slider__dial" role="slider" tabindex="0" :aria-label="label" :aria-valuemin="0" :aria-valuemax="359" :aria-valuenow="local" :aria-valuetext="`${local}°`" :aria-disabled="disabled||undefined" @pointerdown="e=>{e.currentTarget.setPointerCapture(e.pointerId);pointer(e)}" @pointermove="e=>e.buttons&&pointer(e)" @keydown="key"><span class="kima-angle-slider__marker" :style="point"></span><output>{{local}}°</output></div><input class="kima-angle-slider__native" type="number" :value="local" :name="name" min="0" max="359.999" :step="step" :required="required" :disabled="disabled" :aria-label="label" @input.stop="update(Number($event.target.value))" @change.stop="emit('change',local)"></div></template>
